import 'mapping_descriptor.dart';

/// Checks a descriptor before it is used by a feed.
///
/// This is the deterministic guardrail for descriptors written by hand or
/// generated by a build-time LLM: it catches missing canonical fields, empty
/// paths, and contradictory pagination/envelope settings without calling a
/// model at runtime.
List<String> validateFeedMappingDescriptor(
  FeedMappingDescriptor descriptor, {
  required Set<String> requiredFields,
}) {
  final issues = <String>[];

  if (descriptor.itemsPath.trim().isEmpty) {
    issues.add('itemsPath must not be empty');
  }
  if (descriptor.schemaVersion < 1) {
    issues.add('schemaVersion must be >= 1');
  }
  if (descriptor.fields.isEmpty) {
    issues.add('fields must not be empty');
  }

  for (final field in requiredFields) {
    if (!descriptor.fields.containsKey(field)) {
      issues.add('missing required field: $field');
    }
  }

  for (final entry in descriptor.fields.entries) {
    final mapping = entry.value;
    final hasPath = mapping.path?.trim().isNotEmpty ?? false;
    final hasTemplate = mapping.template?.trim().isNotEmpty ?? false;
    if (hasPath == hasTemplate) {
      issues.add('field ${entry.key} must set exactly one of path or template');
    }
    if (mapping.fallbackPath != null && mapping.fallbackPath!.trim().isEmpty) {
      issues.add('field ${entry.key} has an empty fallbackPath');
    }
    if (mapping.transform != null && mapping.transform!.trim().isEmpty) {
      issues.add('field ${entry.key} has an empty transform');
    }
  }

  final hasTotalCount = descriptor.totalCountPath != null;
  final hasPageSize = descriptor.pageSize != null;
  if (hasTotalCount != hasPageSize) {
    issues.add('totalCountPath and pageSize must be set together');
  }
  if (descriptor.pageSize != null && descriptor.pageSize! <= 0) {
    issues.add('pageSize must be positive');
  }
  if (descriptor.hasMorePath != null && hasTotalCount) {
    issues.add('hasMorePath and totalCountPath are mutually exclusive');
  }

  final hasSuccessCode = descriptor.successCode != null;
  final hasSuccessCodePath = descriptor.successCodePath != null;
  if (hasSuccessCode != hasSuccessCodePath) {
    issues.add('successCode and successCodePath must be set together');
  }

  return issues;
}
